css:
:root {
  --crimp-title: #0E5B67;
  --crimp-subtitle: #728DA5;

  --crimp-stage-border: #4B83A7;
  --crimp-stage-number: #1C5A6B;
  --crimp-stage-label: #246975;

  --crimp-separator: #C8DAE5;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.crimp-header-widget {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
}

.crimp-header-svg {
  display: block;
  width: 100%;
  height: 100%;

  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  shape-rendering: geometricPrecision;
}

/* Encabezado */
.crimp-title {
  fill: var(--crimp-title);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0;
}

.crimp-subtitle {
  fill: var(--crimp-subtitle);
  font-size: 21px;
  font-weight: 400;
  letter-spacing: 0;
}

/* Identificadores de las rizadoras */
.crimp-stage-circle {
  fill: url("#crimp-stage-fill");
  stroke: var(--crimp-stage-border);
  stroke-width: 2.2;
}

.crimp-stage-number {
  fill: var(--crimp-stage-number);
  font-size: 23px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-anchor: middle;
  dominant-baseline: central;
}

.crimp-stage-label {
  fill: var(--crimp-stage-label);
  font-size: 20px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Separadores discretos */
.crimp-separators {
  fill: none;
  stroke: var(--crimp-separator);
  stroke-width: 1.2;
  stroke-dasharray: 3 4;
}

js:
"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 2 / RIZADO";

  let titleElement = null;
  let svg = null;
  let latestWidget = null;

  function render(w) {
    if (!titleElement || !svg) return;

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    const title = name || DEFAULT_TITLE;

    // Muestra exactamente el Nombre del inspector.
    titleElement.textContent = title;

    svg.setAttribute(
      "aria-label",
      title +
      ". Rizadoras alternativas: " +
      "Rizadora 1, Rizadora 2, Rizadora 3 y Rizadora 4."
    );
  }

  /*
   * Actualiza el título al cambiar el Nombre del widget.
   * No utiliza variables del PLC.
   * No configura selección ni acciones de clic.
   */
  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    titleElement = document.querySelector(".crimp-title");
    svg = document.querySelector(".crimp-header-svg");

    if (!titleElement || !svg) return;

    render(latestWidget || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
